  {{ include('ui/container/container.html.twig', {'p': {'Class': ui_s(ui_cnv(['mx-auto w-full max-w-6xl px-4', 'py-12'])), 'Attrs': ui_attrs(['data-slot', 'container'])}, 'children': c_14}, with_context = false) }}
{%- endset -%}
{{ include('ui/block/block.html.twig', {'p': {'Tag': 'footer', 'Class': ui_s(ui_cnv(['border-t border-border', (ui_t(ui_eq(v_tone, 'muted')) ? 'bg-muted' : '')])), 'Attrs': ui_attrs(['data-testid', 'footer-split', 'data-layout', v_layout, 'aria-label', v_landmarkLabel])}, 'children': c_15}, with_context = false) }}
